// StreamType:
// #GstStreamType describes a high level classification set for
// flows of data in #GstStream objects.
// 
// Note that this is a flag, and therefore users should not assume it
// will be a single value. Do not use the equality operator for checking
// whether a stream is of a certain type.
type StreamType int

const (
	// The stream is of unknown (unclassified) type.
	StreamTypeUnknown StreamType = C.GST_STREAM_TYPE_UNKNOWN
	// The stream is of audio data
	StreamTypeAudio StreamType = C.GST_STREAM_TYPE_AUDIO
	// The stream carries video data
	StreamTypeVideo StreamType = C.GST_STREAM_TYPE_VIDEO
	// The stream is a muxed container type
	StreamTypeContainer StreamType = C.GST_STREAM_TYPE_CONTAINER
	// The stream contains subtitle / subpicture data.
	StreamTypeText StreamType = C.GST_STREAM_TYPE_TEXT
	// The stream contains metadata.
	StreamTypeMetadata StreamType = C.GST_STREAM_TYPE_METADATA
)

func (s StreamType) String() string {
	return C.GoString(C.gst_stream_type_get_name(C.GstStreamType(s)))
}

